import streamlit as st
import time
import requests

st.set_page_config(
    page_title="MotivaGen",
    page_icon="data:image/png;base64,",
    menu_items={
        "About":"""Join us in spreading joy, motivation, and positivity one image at a time. Start generating your random motivational images now and be part of the inspiration revolution."""
    }
)

st.markdown("## :green[Unleash Instant Inspiration with MotivaGen !]")

st.write("<h5 style='line-height:28px;'>Experience the thrill of endless inspiration and elevate your mood with just a click. Start creating your daily dose of motivation now.</h5>",unsafe_allow_html=True)

btn=st.button(":orange[Motivate Me]")

if btn:
     data=requests.get("https://zenquotes.io/api/image")
     if("zenquotes.io" not in data.text):
        image_url = f"https://zenquotes.io/api/image?timestamp={int(time.time())}"
        st.image(image_url)
     else:
         st.toast("Network Error",icon="🔌")
   
